#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;

const int dx[] = {1, -1, 0, 0};
const int dy[] = {0, 0, 1, -1};

int n, t, rx, ry;
string lab[20], sci[20];
int mem[12][12][12][12][62];
int dist[20][20], vis[20][20];

inline bool good(int x, int y) {
    return 0 <= x && x < n && 0 <= y && y < n && lab[x][y] != 'Y' && lab[x][y] != 'Z';
}

void pre() {
    memset(dist, 0x3f, sizeof(dist));
    memset(vis, 0, sizeof(vis));
    dist[rx][ry] = 0;
    vis[rx][ry] = 1;
    queue<int> qx, qy;
    qx.push(rx);
    qy.push(ry);
    while (!qx.empty()) {
        int x = qx.front(); qx.pop();
        int y = qy.front(); qy.pop();
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (good(nx, ny) && !vis[nx][ny]) {
                dist[nx][ny] = dist[x][y] + 1;
                vis[nx][ny] = 1;
                qx.push(nx);
                qy.push(ny);
            }
        }
    }
}

bool canReach(int x0, int y0, int x1, int y1, int ptr) {
    if (ptr > t) return false;
    int &ret = mem[x0][y0][x1][y1][ptr];
    if (ret != -1) return ret;
    if (x0 == x1 && y0 == y1) return dist[x0][y0] >= ptr;
    if (dist[x0][y0] <= ptr) return ret = 0;
    for (int k = 0; k < 4; k++) {
        int nx = x0 + dx[k];
        int ny = y0 + dy[k];
        if (good(nx, ny) && canReach(nx, ny, x1, y1, ptr + 1)) return ret = 1;
    }
    return ret = 0;
}

struct Dinic {
    struct Edge {
        int to, rev, cap;
    };
    vector<vector<Edge>> g;
    vector<int> level, it;
    Dinic(int n) : g(n), level(n), it(n) {}
    void addEdge(int v, int to, int cap) {
        Edge a{to, (int)g[to].size(), cap};
        Edge b{v, (int)g[v].size(), 0};
        g[v].push_back(a);
        g[to].push_back(b);
    }
    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (const Edge &e : g[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }
    int dfsFlow(int v, int t, int f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[v] + 1 == level[e.to]) {
                int ret = dfsFlow(e.to, t, min(f, e.cap));
                if (ret > 0) {
                    e.cap -= ret;
                    g[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }
    int maxflow(int s, int t) {
        int flow = 0;
        const int INF = 1e9;
        while (bfs(s, t)) {
            fill(it.begin(), it.end(), 0);
            while (true) {
                int pushed = dfsFlow(s, t, INF);
                if (!pushed) break;
                flow += pushed;
            }
        }
        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cout << setprecision(32);

    cin >> n >> t;
    for (int i = 0; i < n; i++) cin >> sci[i];
    for (int i = 0; i < n; i++) cin >> lab[i];

    vector<pair<int, int>> pos;
    vector<int> lc, sc;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (sci[i][j] == 'Z') {
                rx = i;
                ry = j;
            } else if (sci[i][j] >= '0' && sci[i][j] <= '9') {
                pos.push_back({i, j});
                lc.push_back(lab[i][j] - '0');
                sc.push_back(sci[i][j] - '0');
            }
        }
    }

    int m = (int)pos.size();
    pre();
    memset(mem, -1, sizeof(mem));

    Dinic din(2 * m + 2);
    for (int i = 0; i < m; i++) {
        din.addEdge(0, i + 1, sc[i]);
        din.addEdge(m + 1 + i, 2 * m + 1, lc[i]);
    }

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            if (canReach(pos[i].first, pos[i].second, pos[j].first, pos[j].second, 0)) {
                din.addEdge(i + 1, m + 1 + j, 1000);
            }
        }
    }

    cout << din.maxflow(0, 2 * m + 1);
    return 0;
}
